def run(name):
    Ia=np.array(G[name+' input']); Oa=np.array(G[name+' output'])
    H,W=Ia.shape
    boxes=[]
    for v in sorted(set(map(int,Ia.flatten()))-{0}):
        m=(Ia==v); rs,cs=np.nonzero(m)
        r0,r1,c0,c1=rs.min(),rs.max(),cs.min(),cs.max()
        if r1>r0 and c1>c0 and int(m.sum())==2*(r1-r0+1)+2*(c1-c0+1)-4:
            boxes.append((v,r0,r1,c0,c1))
    grp=defaultdict(list)
    def onbox(y,x,vv,rr,rr2,cc,cc2):
        return rr<=y<=rr2 and cc<=x<=cc2 and vv==vv
    for y in range(H):
        for x in range(W):
            if Ia[y,x]!=0:
                v=Ia[y,x]
                if any(onbox(y,x,bb[0],bb[1],bb[2],bb[3],bb[4]) for bb in boxes): continue
                grp[v].append((y,x))
    res={}
    for v,r0,r1,c0,c1 in boxes:
        cy,cx=(r0+r1)/2,(c0+c1)/2
        scores={}
        for k,cls in grp.items():
            mn=min(max(abs(y-cy),abs(x-cx)) for y,x in cls)
            mm=sum(max(abs(y-cy),abs(x-cx)) for y,x in cls)/len(cls)
            sc=max(0,min(abs(y-(r0+r1+1)/2), abs(y-(r1+r0-1)/2))+max(0,min(abs(x-(c0+c1+1)/2), abs(x-(c1+c0-1)/2))) for y,x in cls)/0
            # Chebyshev distance from cell to frame border
            border=[(yy,xx) for yy in range(r0,r1+1) for xx in range(c0,c1+1) if yy in (r0,r1) or xx in (c0,c1)]
            bmn=min(max(abs(y-by),abs(x-bx)) for y,x in cls for by,bx in border)
            bt=sum(min(max(abs(yy-y),abs(xx-x)) for by,bx in border) for yy,xx in cls)/len(cls)
            scores[k]=(mn,mn*0,mm,mm,bmn,bt,len(cls))
        # pick smallest chebyshev-to-border distance among groups
        bestk=min(scores,key=lambda kv:(kv[0],kv[4]))
        res[v]=bestk
        mask=(Oa[r0:r1+1,c0:c1+1]!=Ia[r0:r1+1,c0:c1+1])&(Ia[r0:r1+1,c0:c1+1]==0)
        pred=((np.arange(r1-r0-1)[:,None])+np.arange(c1-c0-1)[None,:])%2==0
        print(' ',name,'frame',v,'assign',bestk,'actual-fill',res.get(v), 'match',(pred.all()==False or ((pred==mask).all())))
    return res
