import numpy as np,json,re
from collections import defaultdict
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def f(grid):
    Ia=np.array(grid); H,W=Ia.shape
    # find rings: exact rectangular perimeters (single-width border of one color, closed box)
    rings=[]
    for v in sorted(set(map(int,Ia.flatten()))-{0}):
        cells=np.argwhere(Ia==v)
        r0,r1,c0,c1=int(cells[:,0].min()),int(cells[:,0].max()),int(cells[:,1].min()),int(cells[:,1].max())
        per=2*(r1-r0-1)+2*(c1-c0-1)+4
        if int(np.sum(Ia==v))==per and r1-r0>=2 and c1-c0>=2:
            # ensure it's a closed rectangle border
            ok=True
            for y in range(r0,r1+1):
                for x in range(c0,c1+1):
                    if y in (r0,r1) or x in (c0,c1):
                        if Ia[y,x]!=v: ok=False
            if ok: rings.append((v,r0,r1,c0,c1))
    def is_ring(y,x):
        for b in rings:
            if b[1]<=y<=b[2] and b[3]<=x<=b[4]: return True
        return False
    # strays: nonzero cells not on any ring border
    strays=[]
    for y in range(H):
        for x in range(W):
            v=int(Ia[y,x])
            if v!=0 and not is_ring(y,x): strays.append((y,x,v))
    # sort rings by topmost row; strays by (count of same color, color value)
    rings.sort(key=lambda b:b[1])
    grp=defaultdict(list)
    for y,x,v in strays: grp[v].append((y,x))
    fill=[g[0] for g in sorted(grp.items(),key=lambda kv:(len(kv[1]),kv[0]))]
    print('rings:',[(b[0],(b[1],b[3])) for b in rings],'strays:',{k:len(v) for k,v in grp.items()},'fill:',fill)
    out=Ia.copy()
    # erase strays
    for y,x,v in strays: out[y,x]=0
    # fill empty even-parity interior cells of each ring
    for idx,(v,r0,r1,c0,c1) in enumerate(rings):
        fillc=fill[idx]
        hh,ww=r1-r0-1,c1-c0-1
        for dy in range(hh):
            for dx in range(ww):
                if (dy+dx)%2==0 and out[r0+dy+1,c0+dx+1]==0:
                    out[r0+dy+1,c0+dx+1]=fillc
    return out.tolist()
for n in ['Demo pair 1','Demo pair 2']:
    pred=f(G[n+' input']); exp=G[n+' output']
    mism=[(i,p,e) for i,(p,e) in enumerate(zip(pred,exp)) if p!=e]
    print(n,'match:',not mism,'ndiff:',len(mism))
print(json.dumps(f(G['Test input'])))
